        return np.sum(np.abs(self.genes - desired_genes))

class Population:
    def __init__(self, size, gene_length):
        self.size = size
        self.gene_length = gene_length
        self.population = [Individual(np.random.randint(0, 255, size=gene_length)) for _ in range(size)]

    def selection(self):
        # Select top individuals based on fitness
        return sorted(self.population, key=lambda ind: ind.fitness())[:int(self.size * 0.2)]

    def crossover(self, parents):
        # Perform crossover between two parents to generate offspring
        child1_genes = np.concatenate((parents[0].genes[:int(self.gene_length / 2)], parents[1].genes[int(self.gene_length / 2):]))
        child2_genes = np.concatenate((parents[1].genes[:int(self.gene_length / 2)], parents[0].genes[int(self.gene_length / 2):]))

        return Individual(child1_genes), Individual(child2_genes)

    def mutation(self, individual):
        # Perform mutation on a single individual
        mutation_rate = 0.01
        mutated_genes = individual.genes.copy()
        for I in range(self.gene_length):
