                mutated_genes[i] = np.random.randint(0, 255)

        return Individual(mutated_genes)

    def evolve(self):
        # Perform selection, crossover, and mutation to generate new population
        parents = self.selection()
        offspring = []
        for I in range(int(self.size * 0.8)):
            child1, child2 = self.crossover(parents[random.randint(0, len(parents) - 1), random.randint(0, len(parents) - 1)])
            offspring.append(child1)
